static const z_t5795_t _zag1805 = { { .data = "ctz64", .size = 5 }, { .length = 1, .data = _zag1804 }, { .length = 0, .data = NULL }, { .data = "#if defined(_MSC_VER) && !defined(__clang__)\n#include <intrin.h>\nstatic inline int z_ctz64(uint64_t v) {\n    unsigned long i;\n    _BitScanForward64(&i, v);\n    return (int)i;\n}\n#else\n#define z_ctz64(v) __builtin_ctzll(v)\n#endif", .size = 227 } };
static const z_t58_t _zag1806[] = {{ .data = "@popcount64", .size = 11 }};

static const z_t5795_t _zag1807 = { { .data = "popcount64", .size = 10 }, { .length = 1, .data = _zag1806 }, { .length = 0, .data = NULL }, { .data = "#if defined(_MSC_VER) && !defined(__clang__)\nstatic inline int z_popcount64(uint64_t v) {\n    v = v - ((v >> 1) & 0x5555555555555555u);\n    v = (v & 0x3333333333333333u) + ((v >> 2) & 0x3333333333333333u);\n    v = (v + (v >> 4)) & 0x0F0F0F0F0F0F0F0Fu;\n    return (int)((v * 0x0101010101010101u) >> 56);\n}\n#else\n#define z_popcount64(v) __builtin_popcountll(v)\n#endif", .size = 365 } };
